from threading import Lock


class NotifyingCreator(type):
    """
    Allows objects to subscribe for notification about other objects creation.
    Notification is made just after creating that other objects.
    """
    __subscribers = []
    __subscribers_lock = Lock()

    @staticmethod
    def notify(subscriber):
        """
        Subscribe for 'object creation notification'
        :param subscriber: function to be called
        :return: None
        """
        with NotifyingCreator.__subscribers_lock:
            if subscriber not in NotifyingCreator.__subscribers:
                NotifyingCreator.__subscribers.append(subscriber)

    @staticmethod
    def stop_notifying(subscriber):
        """
        Unsubscribe from 'object creation notification'
        :param subscriber: function that was previously subscribed
        :return: None
        """
        with NotifyingCreator.__subscribers_lock:
            NotifyingCreator.__subscribers.remove(subscriber)

    def __call__(cls, *args, **kwargs):
        instance = super(NotifyingCreator, cls).__call__(*args, **kwargs)
        # TODO FUTURE: notify only for specified types
        NotifyingCreator.__notify_subscribers(instance)
        return instance

    @staticmethod
    def __notify_subscribers(instance):
        current_subscribers = NotifyingCreator.__subscribers[:]  # copy since calling subscribers may change that list
        for subscriber in current_subscribers:
            subscriber(instance)


class NotifyingClassCreator(type):
    """
    Allows objects to subscribe for notification about specified type objects creation.
    Notification is made just after creating that objects.
    """
    __subscribers = {}
    __subscribers_lock = Lock()

    @staticmethod
    def notify(subscriber, klass):
        """
        Subscribe for 'object creation notification'
        :param subscriber: function to be called
        :param klass: class of object creation notification
        :return: None
        """
        with NotifyingClassCreator.__subscribers_lock:
            if klass not in NotifyingClassCreator.__subscribers:
                NotifyingClassCreator.__subscribers[klass] = [subscriber]
            else:
                if subscriber not in NotifyingClassCreator.__subscribers[klass]:
                    NotifyingClassCreator.__subscribers[klass].append(subscriber)

    @staticmethod
    def stop_notifying(subscriber, klass):
        """
        Unsubscribe from 'object creation notification'
        :param subscriber: function that was previously subscribed
        :param klass: class of object creation notification
        :return: None
        """
        with NotifyingClassCreator.__subscribers_lock:
            NotifyingClassCreator.__subscribers[klass].remove(subscriber)
            if not NotifyingClassCreator.__subscribers[klass]:
                del NotifyingClassCreator.__subscribers[klass]

    def __call__(cls, *args, **kwargs):
        instance = super(NotifyingClassCreator, cls).__call__(*args, **kwargs)
        current_subscribers = NotifyingClassCreator.__subscribers.copy()  # copy since calling subscribers may change that dict
        for klass, subscribers_list in current_subscribers.items():
            if isinstance(instance, klass):
                NotifyingClassCreator.__notify_subscribers(instance, subscribers_list)
                break
        return instance

    @staticmethod
    def __notify_subscribers(instance, subscribers):
        for subscriber in subscribers:
            subscriber(instance)
